import type { CtRuleKey } from './ct-rules';

type Choice = [answer: string, feedback: string];
export type CtSeed = [id: string, rule: CtRuleKey, scenario: string, correct: string, reason: string, ...wrong: [Choice, Choice, Choice]];

export const ctSeeds: CtSeed[] = [
  ['ct-001', 'eligibility', 'A 19-year-old lives in Rhode Island and manages her principal business in New London. What does the ordinary appointment rule allow?', 'She can qualify through her principal Connecticut business.', 'Her Connecticut business can supply the required connection while she lives elsewhere.', ['She must move to Connecticut.', 'The statute also permits a principal Connecticut business.'], ['She must wait until age 21.', 'The minimum application age is 18.'], ['Only a state employee may apply from another state.', 'The ordinary business-connection route is available beyond state employment.']],
  ['ct-002', 'eligibility', 'A 17-year-old Hartford office assistant wants to apply before her birthday so she can work immediately at 18. What should she do?', 'Wait until she is 18 to apply.', 'The age requirement applies at application.', ['Apply now and take the oath later.', 'A later oath does not cure being underage at application.'], ['Get a supervisor’s consent.', 'An employer cannot waive the age requirement.'], ['Submit a character reference instead of proof of age.', 'A recommendation does not replace minimum age.']],
  ['ct-003', 'eligibility', 'A Massachusetts consultant has one Connecticut client and no Connecticut residence or principal business. Which issue must she resolve?', 'She lacks the stated Connecticut residence or principal-business connection.', 'Occasional client work alone does not establish the qualifying connection in the facts.', ['She needs a Connecticut telephone number only.', 'A telephone number is not a statutory qualifying connection.'], ['Any U.S. resident automatically qualifies.', 'The statute requires the stated Connecticut connection.'], ['Paying the fee establishes a principal business.', 'Payment does not create a business location.']],
  ['ct-004', 'eligibility', 'An applicant plans to close his only Connecticut office before appointment and continue living in New York. What must he consider?', 'The Connecticut connection must also exist at appointment.', 'Qualification is required at both application and appointment.', ['The application-day address guarantees the whole term.', 'A qualifying connection must continue.'], ['A postal forwarding address is enough.', 'Mail forwarding does not establish residence or a principal business.'], ['The character signer can lend him a Connecticut address.', 'A reference cannot supply the applicant’s actual qualifying connection.']],
  ['ct-005', 'application', 'A first-time applicant has both required forms ready. Where should she begin the state filing?', 'Use eLicense, then Online Services, Initial Application, Notary Public Certification.', 'The licensing page directs new applicants through that online sequence.', ['Send the forms to this practice website.', 'The practice website does not receive state application materials.'], ['Use the town clerk’s journal-registration page.', 'Town recording happens after appointment.'], ['Buy Pro to create a commission application.', 'A study purchase does not file an official application.']],
  ['ct-006', 'application', 'A former Connecticut notary’s commission has been inactive for several years. He selects the first-time application route. What should he do?', 'Contact the Secretary’s office for reinstatement instructions.', 'The current licensing page directs former notaries with lapsed appointments to reinstatement.', ['Describe himself as a first-time applicant.', 'Prior Connecticut service must be handled accurately.'], ['Begin notarizing while the site processes his form.', 'An inactive appointment supplies no current authority.'], ['Ask a town clerk to extend the old certificate.', 'A town clerk does not grant a new commission term.']],
  ['ct-007', 'application', 'A user finishes Quick 10 and receives a study-site completion screen. What official filing step has this completed?', 'It has completed a practice session only.', 'Official filing and examination occur within the state’s eLicense process.', ['It has submitted the eLicense application.', 'The study session does not submit state forms.'], ['It has reserved a commission number.', 'The study site does not allocate commission numbers.'], ['It has paid the statutory application fee.', 'Practice completion does not transmit an application payment.']],
  ['ct-008', 'application', 'An employer forwards an old printable application and asks a new applicant to mail it. Which current entry should the applicant follow?', 'Follow the Secretary’s current licensing page to eLicense.', 'The forms page says new applications are handled online.', ['Use the old paper application because it has a state logo.', 'A logo does not establish a current filing method.'], ['Upload the form to a public study forum.', 'A study forum is not an official application destination.'], ['Skip the application if the employer keeps the form.', 'Employer records do not replace state filing.']],
  ['ct-009', 'exam', 'A first-time applicant has completed most examination items in eLicense but left one incorrect. What standard remains?', 'Every examination question must be answered correctly before appointment.', 'Manual section 2.2 applies the all-correct requirement to the application examination.', ['An 80% practice result is enough.', 'A practice percentage does not establish the official standard.'], ['Only the identity questions must be correct.', 'The manual applies the requirement to every question.'], ['The character reference can excuse the error.', 'A character recommendation does not waive the examination.']],
  ['ct-010', 'exam', 'A study organizer asks how many items are on the official application examination. The reviewed current sources give no count. What should the organizer publish?', 'Leave the official count unspecified.', 'Only the site’s own practice count is established in this situation.', ['Advertise the site’s 40-item count as official.', 'The site configuration does not establish the state’s item count.'], ['Copy Arizona’s Full 45 count.', 'Another state’s practice count does not establish Connecticut procedure.'], ['Infer ten items from Quick 10.', 'Quick 10 is a site learning mode.']],
  ['ct-011', 'exam', 'A candidate asks whether the state permits a handbook during the application examination. The reviewed sources do not expressly answer. What is the accurate response?', 'The reviewed sources do not establish that permission.', 'Handbook-supported practice does not establish the official examination’s reference-material rules.', ['The practice handbook link proves official permission.', 'Practice UI does not determine state examination conditions.'], ['All online examinations are open book.', 'Online delivery alone establishes no reference-material permission.'], ['A Pro subscription authorizes handbook use.', 'The subscription has no authority over the state examination.']],
  ['ct-012', 'exam', 'A new applicant wants to book an outside exam appointment before opening eLicense. What should the guide explain?', 'The examination is incorporated into the online application.', 'The manual locates the examination in the online application itself.', ['The town clerk administers every application exam.', 'The manual identifies the online application examination.'], ['Quick 10 sends examination results to the Secretary.', 'This site’s practice records are for study.'], ['The character recommender chooses an exam provider.', 'The recommender has no such role in the stated procedure.']],
  ['ct-013', 'jurat-form', 'An applicant types her entire Writing Sample to make it legible. What must she correct?', 'Complete the required writing sample in her own handwriting.', 'The current forms instructions expressly require the applicant’s handwriting.', ['Have her supervisor sign the typed sample.', 'A supervisor’s signature does not create the applicant’s handwriting sample.'], ['Replace it with a typing certificate.', 'A typing certificate is not the required sample.'], ['Submit it unsigned because it is typed.', 'Typing does not excuse completion of the required form.']],
  ['ct-014', 'jurat-form', 'A new applicant signs the jurat at home and uploads it without appearing before an oath administrator. What is missing?', 'The required subscription and oath before an authorized person.', 'The application jurat must be subscribed and sworn to before an authorized oath administrator.', ['A practice-site score attachment.', 'Practice results are not the missing jurat ceremony.'], ['A second character recommendation.', 'The character form does not administer an oath.'], ['An employer’s rubber stamp.', 'An employer stamp does not replace the authorized oath.']],
  ['ct-015', 'jurat-form', 'A clerk offers to write the applicant’s sample while the applicant is present. What should the applicant do?', 'Write the sample herself and arrange the required jurat ceremony.', 'The handwriting must be the applicant’s own.', ['Let the clerk write and initial it.', 'The clerk’s initials do not make the sample the applicant’s handwriting.'], ['Photocopy a coworker’s sample.', 'A copied coworker sample does not satisfy the personal requirement.'], ['Use a character reference in place of the sample.', 'The two documents serve different application requirements.']],
  ['ct-016', 'jurat-form', 'Before uploading the Jurat and Writing Sample, an applicant sees the oath administrator’s section is incomplete. What is the sound next step?', 'Have the required jurat properly completed before uploading.', 'The licensing page identifies incomplete jurats as a common cause of delay.', ['Fill in the oath administrator’s signature herself.', 'The applicant cannot sign for the oath administrator.'], ['Upload only the handwriting portion.', 'The required completed jurat is still missing.'], ['Assume payment repairs the incomplete jurat.', 'Payment does not complete an oath certificate.']],
  ['ct-017', 'character', 'An applicant’s sister is an attorney and has known him all his life. May she complete his Certificate of Character?', 'Use a qualified person unrelated to him instead.', 'The official requirement excludes a legally related recommender.', ['Yes, an attorney is always exempt from the relationship restriction.', 'Professional status does not waive the unrelated-person requirement.'], ['Yes, if she charges no fee.', 'The relationship restriction does not depend on payment.'], ['Yes, because she knows him for more than a year.', 'Length of acquaintance does not remove the family restriction.']],
  ['ct-018', 'character', 'A reputable manager has known an applicant personally for eight months. What is the problem with using that manager now?', 'The personal acquaintance has not reached one year.', 'The character recommender must personally know the applicant for at least a year.', ['The recommender must be a notary.', 'The forms page permits qualifying officials and business or professional people.'], ['Only Connecticut relatives can recommend.', 'The recommender must be unrelated.'], ['The manager must buy a state bond.', 'That is not the stated character-form requirement.']],
  ['ct-019', 'character', 'An unrelated licensed professional has personally known a new applicant for three years and agrees to sign the character form. What should happen?', 'That professional can complete and sign the required recommendation.', 'The facts satisfy the stated professional standing, relationship and acquaintance requirements.', ['The applicant must sign the professional’s name.', 'The recommendation must be signed by its actual recommender.'], ['Only the applicant’s employer can recommend.', 'The permitted class is broader than the applicant’s employer.'], ['A one-year delay is always required after asking.', 'The requirement concerns existing personal acquaintance.']],
  ['ct-020', 'character', 'An applicant leaves the recommender’s signature line empty because the recommender sent a friendly email. What is needed?', 'A fully completed and signed Certificate of Character.', 'The official forms page calls for the certificate to be filled out completely and signed.', ['A screenshot of the email in place of the certificate.', 'The email does not complete the specified certificate.'], ['The applicant’s own favorable review.', 'Self-recommendation does not satisfy the requirement.'], ['An extra practice examination.', 'Practice does not complete a missing character form.']],
  ['ct-021', 'application-fee', 'A first-time ordinary applicant budgets $60 because a coworker paid that amount to renew. What amount applies to the new application?', '$120, nonrefundable.', 'The licensing page distinguishes the new-application fee from renewal.', ['$60, because all online filings cost the same.', 'Renewal and new appointment have different fees.'], ['$20, paid only to the town clerk.', 'Town recording is a separate post-approval expense.'], ['$0 whenever an employer wants a notary.', 'An ordinary private employer request does not establish the state-employee exemption.']],
  ['ct-022', 'application-fee', 'An active Connecticut state employee applies for a commission to use in official duties. What does the current licensing notice allow?', 'Claim the application-fee waiver through the stated employee attestation, subject to audit.', 'The licensing page provides this specific state-employee exception.', ['Ignore all application and oath requirements.', 'The fee exception does not remove the other requirements.'], ['Charge the state’s fee to this practice site.', 'This website is not the application fee collector.'], ['Use a private employer’s badge for the waiver.', 'The notice applies to active state employees using the commission for official duties.']],
  ['ct-023', 'application-fee', 'A private bank employee assumes her bank’s public-service role gives her the active state-employee waiver. What should she expect?', 'The ordinary $120 fee applies absent a qualifying exemption.', 'Employment at a private bank does not meet the stated state-employee exception.', ['Every bank employee is a state employee.', 'Private employment does not establish state employment.'], ['Any payroll statement earns the waiver.', 'The notice requires the specific qualifying employment and use.'], ['Only cash is accepted for the fee.', 'The licensing page lists card and ACH payment options.']],
  ['ct-024', 'application-fee', 'An applicant abandons an ordinary application and wants the statutory fee returned. How is the fee described?', 'It is nonrefundable.', 'The current application instructions expressly describe the $120 fee as nonrefundable.', ['Refundable if no commission is issued.', 'The stated fee rule does not promise that refund.'], ['A refundable equipment deposit.', 'The fee is for the application, not equipment.'], ['A subscription payment to this study service.', 'The statutory payment belongs to the state application process.']],
  ['ct-025', 'oath-record', 'A newly approved notary receives her certificate by email and is asked to notarize immediately. She has not taken the oath. What must happen first?', 'Take the oath of office before performing an act.', 'Receipt of the certificate does not itself administer the oath.', ['Print the email and begin immediately.', 'Printing does not satisfy the oath requirement.'], ['Buy a seal instead of taking the oath.', 'Equipment cannot replace the oath.'], ['Wait five years for a renewal oath.', 'The initial appointment also requires an oath.']],
  ['ct-026', 'oath-record', 'A Connecticut resident lives in Bristol and works in Hartford. Where is mandatory recording of the new appointment and oath?', 'With the Bristol town clerk.', 'For a resident, mandatory recording follows residence.', ['Only with the Hartford employer.', 'Employer files do not satisfy town recording.'], ['Only with any court in the state.', 'The rule identifies the appropriate town clerk.'], ['With the town where the first customer lives.', 'Customer residence does not set the recording location.']],
  ['ct-027', 'oath-record', 'A nonresident appointee’s principal Connecticut business is in Norwalk. Which recording deadline and location apply?', 'Record the certificate and oath in Norwalk within 30 days of receiving the certificate.', 'The rule pairs the nonresident’s principal-business town with the receipt-based deadline.', ['Record in the home state within 90 days.', 'That is neither the stated location nor deadline.'], ['Record after completing the first year of work.', 'The rule requires recording within 30 days of receipt.'], ['Record only the stamp design online.', 'The appointment and oath must be recorded with the town clerk.']],
  ['ct-028', 'oath-record', 'An appointee has taken the oath and is planning the town-clerk visit. Which item belongs in the recording package?', 'The appointment certificate together with the oath of office.', 'The statutory recording requirement covers both the certificate and oath.', ['The study site’s answer sheet.', 'Practice answers are not an appointment record.'], ['Only a purchase receipt for the seal.', 'A seal receipt does not record the appointment.'], ['Only the character recommender’s business card.', 'The character document is part of application preparation.']],
  ['ct-029', 'term', 'A notary submitted a renewal before expiration, but her old commission has expired and the new certificate has not arrived. What should she do?', 'Stop notarial acts until the new appointment and oath requirements are satisfied.', 'A pending renewal does not extend authority after expiration.', ['Keep notarizing during the renewal grace period.', 'The manual says a lapsed commission cannot be used.'], ['Use the old expiration date for another month.', 'A notary cannot extend the date personally.'], ['Ask a customer to waive expiration.', 'Customers cannot grant notarial authority.']],
  ['ct-030', 'term', 'A notary moves permanently out of Connecticut and closes his only Connecticut business. What follows?', 'He must resign when he ceases to meet the Connecticut connection requirement.', 'The required residence or principal-business connection must continue.', ['He keeps authority until the printed expiration regardless.', 'Loss of the qualifying connection affects authority earlier.'], ['A Connecticut mail-forwarding service preserves authority.', 'Mail forwarding alone does not establish the qualifying connection.'], ['His employer may transfer the commission to a replacement.', 'The commission is personal and cannot be transferred.']],
  ['ct-031', 'term', 'An appointment begins in March. Which ordinary term-ending rule should the notary use?', 'Five years later, on the last day of March, subject to earlier termination.', 'The statute uses the last day of the appointment month.', ['Exactly one year after the oath.', 'The ordinary term is five years.'], ['The last day of the purchase year.', 'Purchasing equipment does not determine the term.'], ['Whenever the employer’s notary budget ends.', 'Employer budgeting does not establish the statutory term.']],
  ['ct-032', 'term', 'A notary missed a renewal reminder because her email changed. Who remains responsible for avoiding acts after expiration?', 'The notary remains responsible for the expiration date.', 'The manual places timely renewal responsibility on the notary even without a reminder.', ['The customer must monitor the commission.', 'The customer does not take over the notary’s renewal duty.'], ['The old commission automatically renews.', 'A missed reminder creates no automatic renewal.'], ['The character recommender extends the term.', 'The recommender cannot extend a commission.']],
  ['ct-033', 'id-documents', 'An unfamiliar in-person signer presents only a driver’s license with a photograph and signature. Using the documentary route, what else is needed?', 'A second identification document containing the signer’s signature.', 'The in-person route requires two signed documents, with a photograph or description on at least one.', ['No second document because there is a photograph.', 'A photograph does not eliminate the two-document requirement.'], ['A Social Security card automatically completes the set.', 'The manual excludes Social Security cards as identification.'], ['A promise to bring another ID next week.', 'Identity must be established for the present act.']],
  ['ct-034', 'id-documents', 'A customer presents two signature-bearing documents, one containing her photograph. What statutory feature does that set address?', 'The in-person documentary identity requirements.', 'Both have signatures and at least one supplies the required photograph.', ['It eliminates personal appearance.', 'Identification does not replace appearance.'], ['It proves the contents of her affidavit.', 'Identification does not establish the document’s factual truth.'], ['It grants the notary authority outside Connecticut.', 'Identity documents do not expand territorial authority.']],
  ['ct-035', 'id-documents', 'A signer offers a birth certificate and Social Security card as the only evidence of identity. How should the notary handle that set?', 'Do not accept those as the required identification. Seek an authorized identity route.', 'The manual expressly excludes those documents from identification use.', ['Accept them because both are official records.', 'Official issuance alone does not make them acceptable identification here.'], ['Accept only if the fee is doubled.', 'A higher fee cannot cure deficient identification.'], ['Stamp both cards to make them identification.', 'A seal cannot change the documents’ suitability.']],
  ['ct-036', 'id-documents', 'Two in-person identification documents contain signatures, but neither has a photograph or physical description. What is missing?', 'At least one must also contain a photograph or physical description.', 'Two signatures alone do not complete this documentary route.', ['A character-reference letter from the employer.', 'That is not the missing documentary feature.'], ['A practice score of 100%.', 'Practice performance does not establish identity.'], ['The notary’s own photograph.', 'The required photograph or description concerns the signer.']],
  ['ct-037', 'personal', 'A notary has personally known a neighbor’s identity for many years. The neighbor appears for an acknowledgment without ID documents. Which route may apply?', 'The notary’s genuine personal knowledge.', 'Personal knowledge is a recognized identity basis.', ['A mandatory refusal solely because documents are absent.', 'Personal knowledge is a separate authorized identity route.'], ['A rule allowing every neighbor to identify every customer.', 'The relevant knowledge belongs to the notary in this case.'], ['An exemption from the acknowledgment ceremony.', 'Identity knowledge does not remove the other act requirements.']],
  ['ct-038', 'personal', 'A new walk-in says, “My name is on my jacket, so you personally know me now.” What should the notary do?', 'Use an authorized identification route beyond the introduction.', 'A new self-introduction does not establish genuine personal knowledge.', ['Treat the printed jacket name as personal knowledge.', 'A label supplied by the customer does not create the notary’s knowledge.'], ['Ask for a larger fee and proceed.', 'Payment does not establish identity.'], ['Record the customer’s claim as an oath already administered.', 'A casual statement does not complete a witness oath.']],
  ['ct-039', 'personal', 'An employer introduces a newly hired employee whom the notary has never met. Can the notary claim personal knowledge based only on that introduction?', 'No. Establish identity through another authorized basis.', 'The employer’s introduction does not give the notary existing personal knowledge.', ['Yes, all coworkers are personally known.', 'Sharing an employer does not establish actual personal knowledge.'], ['Yes, if the employee has an office key.', 'An office key does not prove the stated identity.'], ['Yes, if the employer signs the notary’s certificate.', 'The employer cannot supply the notary’s personal knowledge by signing for the notary.']],
  ['ct-040', 'personal', 'A longtime acquaintance appears for a jurat and is personally known to the notary. Which requirement still remains?', 'The signer must sign in the notary’s presence and take an oath or affirmation.', 'The identity basis does not replace the jurat ceremony.', ['Personal knowledge removes the need for any oath.', 'A jurat still requires the oath or affirmation.'], ['The notary must certify that every factual claim is true.', 'The signer vouches for the contents.'], ['A neighbor must sign the notary’s name.', 'Only the commissioned notary signs the certificate.']],
  ['ct-041', 'credible', 'An in-person signer lacks acceptable documents. A coworker personally known to the notary also personally knows the signer. What further step makes that witness route usable?', 'Administer the credible witness an oath or affirmation.', 'The required knowledge relationships and sworn identification work together.', ['Have the coworker merely nod.', 'The manual requires an oath or affirmation.'], ['Use the coworker’s business card as both signer IDs.', 'A witness’s card does not identify the signer through the documentary route.'], ['Let the witness complete the notary’s signature.', 'The witness cannot sign for the notary.']],
  ['ct-042', 'credible', 'A signer brings a friend whom the notary has never met for an ordinary in-person act. Can that friend qualify solely by knowing the signer?', 'No. The in-person credible witness must also be personally known to the notary.', 'Both personal-knowledge relationships are required in this route.', ['Yes, knowing the signer is the only condition.', 'The notary must personally know the credible witness too.'], ['Yes, if the friend waits outside.', 'Waiting outside does not establish the missing knowledge.'], ['Yes, a customer can appoint any witness.', 'The customer cannot waive the identity rule.']],
  ['ct-043', 'credible', 'A notary knows the proposed credible witness well, but the witness met the signer ten minutes earlier. What should happen?', 'Use a different authorized identity basis.', 'The witness must personally know the signer.', ['Proceed because the notary knows the witness.', 'Only one of the required knowledge relationships exists.'], ['Ask the witness to guess the signer’s name under oath.', 'An oath cannot create personal knowledge.'], ['Skip identity because two people attended.', 'The number of attendees does not establish identity.']],
  ['ct-044', 'credible', 'During a credible-witness acknowledgment, the witness is sworn and identifies the signer. What must the signer still do?', 'Personally appear and acknowledge voluntary signing.', 'The witness supplies identity evidence while the signer performs the acknowledgment.', ['The witness can acknowledge for the absent signer.', 'Identity testimony does not replace the signer’s appearance.'], ['The signer can leave before any acknowledgment.', 'The signer must make the required acknowledgment.'], ['The notary can omit the certificate.', 'The act still requires its certificate.']],
  ['ct-045', 'competence', 'At a hospital, a signer cannot explain what she is being asked to sign and is clearly disoriented. What should the notary do?', 'Refuse to proceed while the signer clearly cannot understand the action.', 'The manual requires confidence in the signer’s understanding.', ['Proceed because a relative wants it urgently.', 'Urgency and family wishes do not supply the signer’s understanding.'], ['Diagnose the signer and issue a medical certificate.', 'The notary’s role does not include making a medical diagnosis.'], ['Accept the nurse’s signature in the signer’s place without other authority.', 'That does not complete the signer’s required act.']],
  ['ct-046', 'competence', 'A customer is elderly but converses clearly and explains the document and decision. What approach fits the manual?', 'Assess actual understanding and the usual act requirements.', 'Age alone does not answer whether this person understands the action.', ['Refuse every signer over age 75.', 'The manual does not create that age cutoff.'], ['Ignore identity because the signer is elderly.', 'The usual identity requirement still applies.'], ['Require a doctor’s certificate for every elderly signer.', 'The manual does not impose that blanket requirement.']],
  ['ct-047', 'competence', 'A companion answers every question while the signer remains silent. What is the appropriate next inquiry?', 'Speak with the signer to assess understanding and willingness.', 'The notary should evaluate the signer rather than rely only on a companion.', ['Treat the companion’s answers as the signer’s oath.', 'Another person’s answers do not establish the signer’s solemn commitment.'], ['Ask only whether the fee has been paid.', 'Fee payment does not establish understanding.'], ['Stamp the document before speaking.', 'The notary should resolve the concern before completing the act.']],
  ['ct-048', 'competence', 'A signer understands ordinary conversation but says she has not understood the document she is asked to sign. What should the notary do?', 'Resolve the understanding concern before proceeding, referring legal explanation to qualified counsel.', 'Ability to converse does not alone establish understanding of this action.', ['Explain which legal rights she should surrender.', 'That would exceed the nonattorney notary’s procedural role.'], ['Proceed because conversation proves legal capacity for every document.', 'The present document and action still require attention.'], ['Allow the employer to declare her competent conclusively.', 'The employer cannot substitute a blanket declaration for the notary’s assessment.']],
  ['ct-049', 'voluntary', 'A signer tells a notary privately that a relative threatened him unless he signs. What should the notary do with the acknowledgment?', 'Do not complete it while voluntary execution is lacking.', 'An acknowledgment requires the signer’s voluntary admission.', ['Proceed because his signature matches the ID.', 'A signature match does not establish willingness.'], ['Let the relative acknowledge for him.', 'The relative cannot supply the signer’s voluntary admission.'], ['Charge a coercion surcharge.', 'A payment cannot cure coercion.']],
  ['ct-050', 'voluntary', 'A supervisor says a customer’s consent can be assumed because the appointment was scheduled. What should the notary establish?', 'The signer’s own voluntary acknowledgment.', 'Scheduling is separate from the signer’s free act.', ['Attendance proves voluntary execution conclusively.', 'Attendance alone does not establish voluntariness.'], ['The supervisor may make the acknowledgment.', 'The signer must acknowledge the signer’s own act.'], ['No acknowledgment is needed after scheduling.', 'Scheduling does not remove the notarial ceremony.']],
  ['ct-051', 'voluntary', 'A signer presents a completed agreement but hesitates after being told she has no choice. What is a sound response?', 'Pause and ask the signer directly about willingness.', 'The notary should address apparent pressure before certifying an acknowledgment.', ['Explain why the agreement is financially beneficial.', 'The notary must remain impartial.'], ['Certify willingness based on the document’s printed language alone.', 'Printed language does not establish the signer’s present admission.'], ['Let an impatient customer dictate the certificate.', 'A customer cannot dictate a false notarial statement.']],
  ['ct-052', 'voluntary', 'A notary has established identity and the signer says the earlier signature was voluntary. What does that statement address?', 'The voluntary-execution element of an acknowledgment.', 'The signer admits the act was freely performed for its stated purpose.', ['The notary’s guarantee of all contract terms.', 'Acknowledgment does not guarantee the contract’s legal effect.'], ['The oath required for every jurat.', 'An acknowledgment of execution is distinct from swearing to contents.'], ['The character recommendation for appointment.', 'The statement concerns this document’s execution.']],
  ['ct-053', 'minor', 'A teenager requests an acknowledgment but has no satisfactory ID documents. Which route may help under the manual?', 'A notary who personally knows the minor, or a qualifying credible witness.', 'The minor section identifies these identity alternatives.', ['A parent’s unsigned note automatically replaces identity.', 'A parental note alone is not the specified identity route.'], ['Every minor is exempt from identity checks.', 'Minor signers still require identity verification.'], ['The minor must become a notary first.', 'Commission eligibility is unrelated to identifying a minor signer.']],
  ['ct-054', 'minor', 'A minor’s identity is established, but the notary asks whether the minor understands the document. Is that inquiry appropriate?', 'Yes. Understanding remains part of the notary’s assessment.', 'The manual specifically discusses competence for minor signers.', ['No, identity settles every issue.', 'Identity and understanding are separate.'], ['No, the parent always substitutes for the minor.', 'A parent’s presence does not erase the signer’s own role.'], ['No, minors automatically lack all understanding.', 'The manual calls for an actual assessment.']],
  ['ct-055', 'minor', 'A parent asks a nonattorney notary to decide whether her child’s contract is enforceable. What is the proper boundary?', 'Refer the legal-effect question to an attorney.', 'The manual distinguishes notarization from deciding whether a minor can legally execute a particular instrument.', ['Guarantee enforceability after notarizing.', 'The notary’s certificate does not make that legal determination.'], ['Rewrite the contract to bind the child.', 'That is legal work beyond the commission.'], ['Use the seal as parental consent.', 'The notarial seal does not supply parental consent.']],
  ['ct-056', 'minor', 'A school asks a notary to skip the minor signer’s appearance because a parent delivered the signed form. What should happen?', 'Require the signer’s appearance and applicable identity and understanding checks.', 'Delivery by the parent does not complete the minor’s personal notarial act.', ['The parent can simply describe the signature.', 'A description does not substitute for appearance.'], ['The school letterhead waives appearance.', 'Letterhead does not waive the act requirements.'], ['The notary may certify the child’s school grades instead.', 'That does not perform the requested notarial act.']],
  ['ct-057', 'mark', 'A competent signer cannot write and wishes to sign with a mark. What should the notary consult?', 'The manual’s signature-by-mark procedure and witness requirements.', 'A mark can be used under the described procedure.', ['A rule authorizing the notary to sign the signer’s name freely.', 'The notary should not substitute a personal signature for the signer’s act.'], ['A blanket rule that every nonwriting signer is incompetent.', 'Inability to write does not itself establish lack of understanding.'], ['Only the remote-identity rules.', 'The question concerns the mark procedure for the signer’s act.']],
  ['ct-058', 'mark', 'An office proposes placing a typed X on a form while the signer stays home. Does the mark procedure solve the appearance problem?', 'No. The applicable appearance and other requirements still apply.', 'A mark is a signature method and does not eliminate the notarial ceremony.', ['Yes, an X has no appearance requirement.', 'The method of signing does not waive appearance.'], ['Yes, if the office manager prints the X.', 'The manager’s typing does not complete the signer’s act.'], ['Yes, if the notary adds a second seal.', 'Extra seals cannot replace appearance.']],
  ['ct-059', 'mark', 'A signer using a mark understands the document and appears before the notary. Which concern remains to be addressed?', 'Identity and the manual’s required mark safeguards.', 'Understanding alone does not complete identification and procedure.', ['Only whether the mark looks artistic.', 'The procedure concerns identity and execution safeguards.'], ['Whether the notary can take ownership of the document.', 'Ownership is not a requirement of a mark notarization.'], ['Whether the signer can pay double.', 'A higher payment does not replace the required safeguards.']],
  ['ct-060', 'mark', 'A clerk says the notary may skip the mark witnesses because the signer is a regular customer. What is the better approach?', 'Follow the manual’s mark procedure even for a familiar customer.', 'Personal familiarity does not remove the procedural safeguards for this signature method.', ['Let familiarity waive all witnesses.', 'Identity knowledge does not waive the mark procedure.'], ['Replace the mark with the clerk’s signature.', 'The clerk’s signature is not the signer’s own act.'], ['Describe the mark as a government ID.', 'A signature method is not an identification document.']],
  ['ct-061', 'appearance', 'A courier delivers an owner’s signed acknowledgment document while the owner is away. What should the notary do?', 'Arrange the owner’s required appearance before completing the act.', 'The signed document’s delivery does not replace the signer’s appearance.', ['Acknowledge the courier’s delivery as the owner’s act.', 'The courier cannot acknowledge for the absent owner merely by delivery.'], ['Use a photograph of the owner instead.', 'A photograph alone does not supply appearance.'], ['Ask the courier to pay and proceed.', 'Payment does not cure missing appearance.']],
  ['ct-062', 'appearance', 'An unfamiliar customer offers a recorded video of herself signing yesterday for an ordinary in-person jurat. Is that enough?', 'No. Complete an authorized appearance and jurat procedure.', 'A prerecorded video does not perform the required in-person or live remote ceremony.', ['Yes, any video substitutes for appearance.', 'A recording lacks simultaneous interaction.'], ['Yes, if the recording is high resolution.', 'Image quality does not establish the required ceremony.'], ['Yes, because a jurat needs no oath.', 'A jurat requires an oath or affirmation.']],
  ['ct-063', 'appearance', 'A client calls by telephone and asks for an acknowledgment using a signature the notary recognizes. What is missing for the proposed ordinary act?', 'The required appearance before the notary.', 'Familiarity with a signature does not replace appearance.', ['A second telephone call only.', 'Repeating a voice call does not establish the required appearance.'], ['The notary’s opinion of the client’s business.', 'A business opinion is unrelated to appearance.'], ['A notarization purchase receipt.', 'Payment documentation does not supply the ceremony.']],
  ['ct-064', 'appearance', 'An office wants to move a planned in-person act to video. What should the notary check before agreeing?', 'Whether the separate remote procedure and document restrictions can all be satisfied.', 'A change in medium requires compliance with section 3-95b.', ['Only whether the camera turns on.', 'A working camera alone does not satisfy remote identity and document rules.'], ['Whether the customer promises to accept every risk.', 'The customer cannot waive statutory requirements.'], ['Whether the in-person certificate can be left unchanged automatically.', 'Remote appearance requires appropriate certificate wording.']],
  ['ct-065', 'ack', 'A tenant appears, proves identity and says the lease signature is her free act for its stated purpose. Which act fits those facts?', 'An acknowledgment.', 'The signer is admitting voluntary execution.', ['A jurat without an oath.', 'A jurat requires an oath or affirmation and signing in the notary’s presence.'], ['A copy certification.', 'No copy-comparison procedure is described.'], ['An appointment oath for the notary.', 'The signer is acknowledging a document, not taking office.']],
  ['ct-066', 'ack', 'A customer asks whether acknowledging his signature makes the notary a party to the contract. What should the notary explain?', 'The certificate records the signer’s acknowledgment.', 'The notary certifies the act performed rather than joining the agreement.', ['The notary becomes a guarantor of payment.', 'An acknowledgment does not create that guarantee.'], ['The notary approves every commercial term.', 'The act does not express legal or commercial approval.'], ['The seal transfers the contract to the state.', 'A notarial seal does not transfer ownership.']],
  ['ct-067', 'ack', 'A business officer appears to acknowledge signing for the corporation. What should the certificate accurately reflect?', 'The officer’s acknowledgment in the stated representative capacity.', 'The manual provides a representative-capacity acknowledgment sample.', ['That the notary elected the officer.', 'The act does not establish that the notary elected anyone.'], ['That every corporate fact has been independently certified by the notary.', 'The acknowledgment does not authorize certification of corporate facts.'], ['That no person appeared because the signer is a corporation.', 'An individual officer appears and acknowledges the act.']],
  ['ct-068', 'ack', 'A signer proves identity but refuses to admit signing the document voluntarily. Can the notary complete the requested acknowledgment?', 'No. The required voluntary acknowledgment is missing.', 'Identity alone does not complete an acknowledgment.', ['Yes, identity is the only element.', 'The signer’s admission of voluntary execution is also required.'], ['Yes, if a clerk recognizes the signature.', 'Recognition by a clerk does not provide the missing acknowledgment.'], ['Yes, if the notary changes the act date.', 'Changing dates cannot supply the missing ceremony.']],
  ['ct-069', 'pre-signed', 'A customer signed an agreement yesterday and appears today to acknowledge it. What date belongs to today’s acknowledgment?', 'Today’s actual acknowledgment date.', 'A prior signature may be acknowledged, while the notarial act is dated when it occurs.', ['Yesterday, to match the signature automatically.', 'That would misstate when the notarial act occurred.'], ['Tomorrow, to allow processing.', 'The certificate cannot certify a future act.'], ['The commission-expiration date.', 'Expiration is separate from the act date.']],
  ['ct-070', 'pre-signed', 'A notary receives an acknowledgment document bearing a signature date later than today. What should be resolved?', 'The inconsistent future signature date before proceeding.', 'The manual says an acknowledgment signature date must not be later than notarization.', ['Use a future notarial date to match.', 'A notary must not certify a future act.'], ['Ignore all document dates.', 'The stated future signature date creates a relevant inconsistency.'], ['Call the document a jurat automatically.', 'Changing the act label does not resolve the date issue.']],
  ['ct-071', 'pre-signed', 'A clerk insists every acknowledgment must be re-signed because the customer signed at home. Which specific manual rule applies?', 'An earlier signature may be acknowledged when the signer properly appears and acknowledges it.', 'Section 4.2 specifically distinguishes acknowledgments from jurats.', ['Every earlier signature is automatically invalid.', 'The specific acknowledgment rule permits an earlier signature.'], ['Earlier signing removes the need for appearance.', 'The signer must still appear.'], ['An earlier signature is automatically an oath.', 'Signing alone does not administer an oath.']],
  ['ct-072', 'pre-signed', 'An affidavit requiring a jurat arrives already signed. The customer offers to acknowledge the old signature without signing before the notary. What is required for the jurat?', 'Signing in the notary’s presence plus an oath or affirmation.', 'The earlier-signature allowance for acknowledgments does not replace jurat requirements.', ['Use acknowledgment rules and label it a jurat.', 'The certificate must match the act actually performed.'], ['Certify the signature without meeting the customer.', 'A jurat requires the signer’s appearance and ceremony.'], ['Ask the customer to mail a second old signature.', 'Mailing another prior signature does not supply the required act.']],
  ['ct-073', 'jurat', 'A customer signs an affidavit in front of a notary but no oath or affirmation occurs. What remains before a jurat can be completed?', 'Administer the oath or affirmation about the signed document’s truth.', 'Witnessing a signature supplies only part of a jurat.', ['Only affix a second seal.', 'An extra seal cannot administer an oath.'], ['Ask the customer to pay the application fee.', 'The appointment fee is unrelated to this act.'], ['Nothing, the affidavit title supplies the oath.', 'A document title does not perform the required ceremony.']],
  ['ct-074', 'jurat', 'A signer swears the affidavit is true but has not signed it. What does the notary still need for the jurat?', 'The signer’s voluntary signature in the notary’s presence.', 'The jurat requires both the signature and the solemn commitment.', ['The notary may sign the signer’s name.', 'The notary cannot substitute a signature for the signer’s act.'], ['The oath makes every signature optional.', 'A jurat includes a signature requirement.'], ['A character reference can sign instead.', 'The recommender has no role in this affidavit’s execution.']],
  ['ct-075', 'jurat', 'The certificate says “subscribed and sworn to,” but the customer only wants to confirm having signed. What should happen?', 'Clarify the required act and complete the ceremony matching the certificate.', 'The jurat language calls for signing and an oath or affirmation.', ['Use the jurat language despite performing only an acknowledgment.', 'That would misdescribe the act.'], ['Cross out the signer’s name and insert the notary’s.', 'That does not resolve which act is required.'], ['Treat the certificate as optional decoration.', 'Certificate language records the notarial act.']],
  ['ct-076', 'jurat', 'An office assistant signs an employee’s affidavit while the employee takes the oath. Is this the ordinary jurat described in the manual?', 'No. The employee’s own voluntary signature in the notary’s presence is required.', 'The described jurat links the identified signer’s signature and oath.', ['Yes, anyone may supply the signature.', 'The ordinary jurat does not permit that substitution.'], ['Yes, if the assistant is the notary’s employer.', 'Employer status does not cure a substituted signature.'], ['Yes, if the assistant is not charged a fee.', 'Fee treatment does not satisfy the missing signer action.']],
  ['ct-077', 'affirmation', 'A signer objects to religious language in an affidavit ceremony. What can the notary offer?', 'A solemn affirmation.', 'The manual recognizes an affirmation as the appropriate nonreligious alternative.', ['Refusal solely because the signer rejects religious language.', 'An affirmation provides a lawful alternative.'], ['No commitment of truth at all.', 'The jurat still requires an oath or affirmation.'], ['A promise from the notary instead.', 'The signer must make the commitment.']],
  ['ct-078', 'affirmation', 'A customer asks whether affirming makes lying in the statement harmless. What should the notary explain?', 'An affirmation carries the solemn truthfulness obligation.', 'The nonreligious form does not remove the legal seriousness of the statement.', ['Affirmations are casual conversation.', 'An affirmation is a solemn declaration.'], ['Only an oath can support a jurat.', 'An affirmation may serve the same role.'], ['A notary assumes liability for every statement the signer makes.', 'The signer remains responsible for the statement’s contents.']],
  ['ct-079', 'affirmation', 'A form uses “swear,” and the signer requests an affirmation. Which procedure respects the signer’s choice?', 'Administer the corresponding solemn affirmation.', 'Connecticut recognizes affirmation in place of an oath.', ['Require the signer to use religious words.', 'The lawful affirmation alternative should be available.'], ['Let the signer skip the entire jurat.', 'The notarial ceremony still must occur.'], ['Have a bystander affirm for the signer.', 'The person making the statement must make the commitment.']],
  ['ct-080', 'affirmation', 'A notary tells a signer that an affirmation requires no response. What is the better procedure?', 'Obtain the signer’s affirmative solemn commitment.', 'An affirmation must actually be made by the signer.', ['Treat silence as the completed affirmation automatically.', 'Silence does not establish the required commitment.'], ['Use the seal as the signer’s response.', 'The notary’s equipment cannot speak for the signer.'], ['Ask the employer to answer instead.', 'The employer does not make the signer’s statement.']],
  ['ct-081', 'oath-ceremony', 'A customer nods toward a printed affidavit and leaves before any oath is administered. What should the notary avoid?', 'Certifying that an oath was administered when none occurred.', 'The certificate must reflect the actual ceremony.', ['Calling the customer back for the required act.', 'Arranging the actual ceremony is appropriate.'], ['Checking identity at the completed appointment.', 'Identity verification is part of proper procedure.'], ['Explaining the oath procedure.', 'A procedural explanation helps the signer complete the act.']],
  ['ct-082', 'oath-ceremony', 'A busy notary plans to stamp a stack of affidavits first and administer oaths to the signers later. What is the appropriate sequence?', 'Perform each required ceremony before completing its certificate.', 'The certificate records an act actually carried out.', ['Certify future oaths based on the appointment list.', 'A planned ceremony is not a completed act.'], ['Administer one oath to an absent group.', 'Absent signers have not participated in the required ceremony.'], ['Use payment as a substitute for every oath.', 'Payment does not administer an oath.']],
  ['ct-083', 'oath-ceremony', 'A signer appears, is identified and signs, but says she will decide tomorrow whether to swear to the contents. Can the notary complete today’s jurat?', 'No. The required present oath or affirmation has not occurred.', 'A later decision does not supply the ceremony for a certificate completed today.', ['Yes, because the signature is complete.', 'A signature is only part of the jurat.'], ['Yes, if tomorrow’s date is guessed.', 'A notary cannot certify a future ceremony.'], ['Yes, if the affidavit is important.', 'Importance does not remove the oath requirement.']],
  ['ct-084', 'oath-ceremony', 'A receptionist reports that a signer swore privately in the waiting room. What must the notary do for the jurat?', 'Administer the oath or affirmation as part of the notary’s own act.', 'The notary cannot certify personally administering an oath based solely on a receptionist’s account.', ['Certify the receptionist’s report as personal observation.', 'A report does not become the notary’s own ceremony.'], ['Omit the oath date permanently.', 'Omitting a date does not perform the missing act.'], ['Let the receptionist use the notary’s seal.', 'Only the named notary may use the seal.']],
  ['ct-085', 'act-choice', 'A customer brings a document with no certificate and asks which act will make it legally enforceable. What should a nonattorney notary do?', 'Refer the legal-choice question to the receiving party or an attorney.', 'The notary can explain procedures while avoiding a legal-effect decision.', ['Choose the act that gives the customer the most rights.', 'That would involve legal advice.'], ['Stamp the margin without a certificate.', 'A bare stamp does not record an appropriate completed act.'], ['Guarantee enforceability after payment.', 'A commission does not authorize that guarantee.']],
  ['ct-086', 'act-choice', 'A signer asks the difference between acknowledging execution and swearing to contents. What may the notary explain?', 'The procedural difference between the two notarial acts.', 'Explaining how acts work is distinct from choosing a legal strategy for the signer.', ['Which contract rights the signer should surrender.', 'That would advise on legal consequences.'], ['That both acts always mean the notary verifies every fact.', 'The signer’s statements and the notary’s role differ.'], ['That any certificate may be used regardless of the act.', 'Certificate wording must match the actual act.']],
  ['ct-087', 'act-choice', 'A lender’s instructions conflict with the certificate supplied to the signer. What is a sound next step?', 'Obtain clarification of the required act before notarizing.', 'Uncertainty should be resolved so the act and certificate correspond.', ['Invent a hybrid certificate guaranteeing the loan.', 'The notary should not invent legal guarantees.'], ['Complete whichever act is faster without asking.', 'Speed does not resolve the conflict.'], ['Let the loan amount decide the act.', 'The amount alone does not determine the required certificate.']],
  ['ct-088', 'act-choice', 'A customer wants the notary to fill in the substantive terms of a power of attorney before notarizing. What is the appropriate boundary?', 'Refer substantive legal drafting to an attorney.', 'The commission does not authorize a nonattorney to prepare the legal instrument for the customer.', ['Select the broadest powers for the customer.', 'Choosing substantive powers is legal advice.'], ['Use a seal to fill blank legal terms.', 'A seal does not supply substantive document content.'], ['Certify that blank provisions are enforceable.', 'The notary does not determine legal enforceability.']],
  ['ct-089', 'territory', 'A Hartford notary travels to Springfield, Massachusetts, with a Connecticut customer. Does the Connecticut commission authorize an act there?', 'No. The Connecticut commission does not authorize acts physically performed outside Connecticut.', 'The relevant location is where the notary performs the act.', ['Yes, because the customer lives in Connecticut.', 'Customer residence does not expand the notary’s territory.'], ['Yes, if the seal says Connecticut.', 'A seal does not extend territorial authority.'], ['Yes, if the document returns to Hartford.', 'The destination does not authorize the act’s out-of-state location.']],
  ['ct-090', 'territory', 'A notary recorded her appointment in Stamford and receives a lawful request in New Haven. What does town recording imply about territory?', 'She may act elsewhere within Connecticut if all requirements are met.', 'A Connecticut appointment provides statewide authority.', ['She may act only in Stamford.', 'Recording does not reduce authority to one town.'], ['She must buy a second commission for New Haven.', 'A separate town commission is not required for statewide authority.'], ['She may now act in every state.', 'Statewide authority is limited to Connecticut.']],
  ['ct-091', 'territory', 'A Connecticut notary vacationing in Florida offers video notarization under his Connecticut commission. Where should he be for a Connecticut remote act?', 'Physically in Connecticut.', 'The current manual requires the Connecticut notary to remain in the state.', ['Anywhere with internet access.', 'An internet connection does not expand territorial authority.'], ['At any airport serving Connecticut flights.', 'Flight connections do not establish Connecticut location.'], ['Wherever the signer wants.', 'The signer does not control the notary’s territorial authority.']],
  ['ct-092', 'territory', 'A Connecticut notary acts in Danbury on a document intended for another state. What should she check?', 'The applicable Connecticut act requirements and the receiving party’s certificate needs.', 'An out-of-state destination does not itself move the notary outside Connecticut.', ['Automatically refuse every document used elsewhere.', 'The document’s destination alone does not defeat Connecticut authority.'], ['Use the destination state’s venue instead of Danbury.', 'Venue records where the act occurs.'], ['Claim a commission from the receiving state.', 'The document’s destination does not grant another commission.']],
  ['ct-093', 'content', 'An affidavit states a delivery arrived on time. Must the notary independently investigate that delivery to administer the jurat?', 'The signer vouches for the contents through the oath or affirmation.', 'The jurat does not turn the notary into the investigator of the delivery facts.', ['The seal independently proves timely delivery.', 'A seal does not establish the underlying fact.'], ['The notary must sign as the delivery recipient.', 'That would substitute a different factual role.'], ['No oath is needed for business facts.', 'An affidavit jurat still requires the oath or affirmation.']],
  ['ct-094', 'content', 'A customer asks whether a notarized agreement is guaranteed lawful. What is the accurate explanation?', 'The notarization records the notarial act performed.', 'The notary’s act does not guarantee the agreement’s legal effect.', ['Every notarized agreement is enforceable.', 'Notarization does not settle enforceability.'], ['The state becomes a contracting party.', 'The notarial act does not make the state a party.'], ['All document defects disappear after a seal is added.', 'A seal does not repair substantive legal defects.']],
  ['ct-095', 'content', 'A signer admits an affidavit’s contents were fabricated to deceive a lender. Can the notary rely on “the signer owns the contents” and proceed?', 'No. Refuse participation in the fraudulent official act.', 'The limited factual role does not authorize an act intended to deceive.', ['Yes, a sworn lie is always the notary’s required service.', 'The fraud prohibition still applies.'], ['Yes, if the notary avoids reading the admitted falsehood.', 'Ignoring admitted deception does not authorize the act.'], ['Yes, with a written fee waiver.', 'Fee arrangements do not cure fraudulent intent.']],
  ['ct-096', 'content', 'A recipient reads an acknowledgment as a notary’s opinion that the contract is a good investment. What should the notary clarify?', 'The act concerns the signer’s acknowledged execution.', 'The certificate does not endorse an investment.', ['The notary guarantees all investment returns.', 'The commission authorizes no such guarantee.'], ['The notary has audited the business.', 'Acknowledgment does not establish an audit.'], ['The customer bought a state investment license.', 'A notarization does not issue that license.']],
  ['ct-097', 'certificate', 'A signer appears and completes the required act, but the document has only a blank stamp box. What must the notary provide?', 'An appropriate completed notarial certificate.', 'The certificate records the act and required facts.', ['Only an embossed seal.', 'A seal alone does not supply the certificate.'], ['Only a receipt.', 'A payment receipt does not certify the notarial act.'], ['The study site’s terms of service.', 'Those terms are unrelated to the document’s certificate.']],
  ['ct-098', 'certificate', 'A notary uses a jurat certificate after performing only an acknowledgment. What needs correction?', 'The certificate must accurately match the act performed.', 'Different certificate words describe different acts.', ['Nothing, any notarial wording is interchangeable.', 'An acknowledgment and jurat have distinct requirements.'], ['Only the document’s font.', 'The mismatch is substantive to the notarial certificate.'], ['Only the customer’s mailing address.', 'Changing an address does not fix the act description.']],
  ['ct-099', 'certificate', 'A customer asks for a notary’s seal on an otherwise blank page to attach to another document later. What is appropriate?', 'Decline to issue a bare seal for later attachment.', 'A completed certificate must correspond to an actual act and document.', ['Give three impressions to save future visits.', 'Extra impressions would not establish completed acts.'], ['Charge enough to guarantee future accuracy.', 'A higher fee cannot establish future facts.'], ['Ask the customer to select an act afterward.', 'The certificate must reflect the act actually performed.']],
  ['ct-100', 'certificate', 'An acknowledgment form has blanks for the signer, act date and notary. May the notary leave those details for the recipient?', 'Complete the required certificate facts accurately as part of the act.', 'Required certificate facts are the notary’s responsibility in completing the act.', ['Yes, recipients can certify what the notary observed.', 'A later recipient cannot supply the notary’s observations.'], ['Yes, if the seal is clear.', 'A clear seal does not complete factual blanks.'], ['Yes, because all blanks are cosmetic.', 'These blanks identify the act and participants.']],
  ['ct-101', 'venue', 'A document concerns a Stamford property, but the signer appears before the notary in Hartford. What location should the venue reflect?', 'The Hartford location of the act.', 'Venue concerns where the notarization happens.', ['Stamford solely because the property is there.', 'Property location does not determine this act’s venue.'], ['The signer’s birthplace.', 'Birthplace does not identify the act location.'], ['The notary’s equipment vendor’s town.', 'The vendor is unrelated to venue.']],
  ['ct-102', 'venue', 'A preprinted certificate says New York, but the entire in-person act occurs in Connecticut. What should the notary address?', 'Correctly identify the actual Connecticut venue.', 'A preprinted location must not misstate where the act occurs.', ['Leave New York because printed text is always conclusive.', 'Preprinting does not make a false location accurate.'], ['Travel mentally to the printed venue.', 'The physical location of the act controls.'], ['Use the mailing destination as the venue.', 'Mail destination is a separate fact.']],
  ['ct-103', 'venue', 'A signer asks whether “ss.” in a certificate is the signer’s Social Security number field. What does the manual explain?', 'It identifies the particular place within the venue.', 'The manual explains the abbreviation as referring to the specific location.', ['It requires the full Social Security number.', 'The abbreviation does not request that number.'], ['It authorizes a second signature stamp.', 'It is venue terminology.'], ['It gives the notary interstate authority.', 'Venue wording does not expand authority.']],
  ['ct-104', 'venue', 'A notary performs acts at several client offices during one day. What should each certificate’s venue reflect?', 'The location of that particular act.', 'A route through several towns does not create one venue for every act.', ['The first office visited for every certificate.', 'Later acts occur at their own locations.'], ['The customer’s preferred town regardless of facts.', 'A preference cannot change the location.'], ['The notary’s bank account address.', 'A banking address does not set venue.']],
  ['ct-105', 'date', 'A customer missed a filing deadline and asks a notary to date today’s act last Friday. What should the notary do?', 'Use the actual act date and decline backdating.', 'A deadline does not authorize a false certificate date.', ['Backdate if both parties consent.', 'Consent cannot authorize false notarial facts.'], ['Use Friday but add a larger seal.', 'Equipment does not cure a false date.'], ['Leave the date for the customer to invent.', 'Required certificate facts must be accurate.']],
  ['ct-106', 'date', 'A signer wants a certificate dated next month because the document will be used then. Which date is appropriate for today’s in-person act?', 'Today’s actual act date.', 'Future use is separate from the date of notarization.', ['Next month’s intended use date.', 'That would certify an act on a future date.'], ['The day the document is mailed.', 'Mailing is not the notarial act.'], ['The customer’s birthday.', 'That has no connection to the act date.']],
  ['ct-107', 'date', 'An acknowledgment involves a signature made last week and an appearance today. Which two dates may legitimately differ?', 'The document’s earlier signature date and today’s acknowledgment date.', 'The specific acknowledgment procedure permits an earlier signature.', ['The true act date and a fabricated certificate date.', 'The certificate must state the actual act date.'], ['The notary’s actual expiration and an extended expiration chosen by the client.', 'A client cannot extend the commission.'], ['The notary’s attendance and a certificate claiming no attendance.', 'The certificate must accurately describe appearance.']],
  ['ct-108', 'date', 'A notary discovers an unsigned certificate prepared in advance for an appointment that never occurred. What should she avoid?', 'Completing it as if the missed appointment happened.', 'A prepared form does not establish a completed act.', ['Leaving the act unperformed until the signer attends.', 'Waiting for the actual act is appropriate.'], ['Checking the scheduled appointment record.', 'Checking facts is appropriate.'], ['Explaining that a new appointment is needed.', 'A new actual ceremony can address the missing act.']],
  ['ct-109', 'signature', 'A notary’s assistant offers to sign the certificate with the notary’s name during lunch. What is allowed?', 'Only the notary may apply the notary’s own required original signature.', 'The assistant cannot sign on behalf of the commissioned notary.', ['The assistant may sign if the employer approves.', 'Employer permission does not transfer the commission.'], ['The assistant may sign if no fee is charged.', 'Free service still requires the proper notary’s act.'], ['The assistant may sign with a different colored pen.', 'Ink color does not cure unauthorized signing.']],
  ['ct-110', 'signature', 'A notary orders a rubber stamp reproducing her handwritten signature. Can it replace her original certificate signature?', 'No. The manual requires the original signature.', 'A signature stamp is expressly distinguished from the required original signature.', ['Yes, if ordered from a notary vendor.', 'Vendor status does not waive the signature requirement.'], ['Yes, if the customer prefers it.', 'Customer preference does not alter the duty.'], ['Yes, if used with an embossing seal.', 'A seal does not replace the original signature.']],
  ['ct-111', 'signature', 'The appointment certificate lists a notary’s full name, but she wants to sign notarial certificates with an unrelated nickname. What should she do?', 'Sign exactly as the name appears on the appointment certificate.', 'The official signature must correspond to the appointment name.', ['Use any nickname coworkers recognize.', 'Coworker recognition does not change the appointment name.'], ['Let the signer choose her signature name.', 'The signer cannot change the notary’s official name.'], ['Omit the signature and print the nickname.', 'Printing alone does not supply the original signature.']],
  ['ct-112', 'signature', 'An otherwise completed certificate has a seal and printed name but no notary signature. What is still needed?', 'The notary’s required original signature.', 'The printed name and seal do not sign the certificate.', ['A second printed copy only.', 'Another copy repeats the missing signature.'], ['The customer’s initials instead.', 'The customer cannot sign for the notary.'], ['A business-card attachment instead.', 'A card does not supply the certificate signature.']],
  ['ct-113', 'expiration', 'A notary signs a certificate without a seal or stamp. What identifying wording must she include near the official signature?', 'Notary Public and the commission-expiration date, with the name legibly identified.', 'Section 3-94k and the manual describe the information needed without equipment.', ['Only the customer’s address.', 'That does not identify the notary’s office and expiration.'], ['Only the act fee.', 'The fee does not supply commission information.'], ['Only the document’s page count.', 'Page count does not identify the appointment.']],
  ['ct-114', 'expiration', 'A stamp includes the notary’s name and title but leaves “My commission expires” blank. What must the notary do?', 'Supply the actual commission-expiration date.', 'The missing date must be completed accurately.', ['Use today’s act date as expiration.', 'The act date and expiration date are different facts.'], ['Use the customer’s filing deadline.', 'A filing deadline does not determine commission expiration.'], ['Leave it blank because a stamp exists.', 'Equipment does not excuse missing required information.']],
  ['ct-115', 'expiration', 'A notary’s certificate was replaced after a name change. May she assume the replacement starts a fresh five-year term?', 'No. Use the appointment’s actual expiration information.', 'A replacement identifying document does not itself grant a new term.', ['Yes, every replacement creates five more years.', 'Replacement and renewal are separate processes.'], ['Yes, the stamp vendor sets the term.', 'A vendor cannot grant notarial authority.'], ['Yes, if the name change cost $15.', 'The name-change fee is not a new appointment term.']],
  ['ct-116', 'expiration', 'A customer says the expiration date can be omitted because she checked the notary’s license online. What should the notary do?', 'Include the required expiration information in the certificate.', 'A recipient’s outside lookup does not replace the certificate requirement.', ['Omit it whenever the customer agrees.', 'Customer agreement does not remove the requirement.'], ['Write the license-lookup website instead.', 'A URL does not supply the expiration date.'], ['Print only the year of the act.', 'The act year is separate from the commission-expiration date.']],
  ['ct-117', 'copy-process', 'A customer brings only two photocopies of a private letter and asks the notary to certify one against the other. What is missing?', 'The original document required for the copy-certification procedure.', 'Comparing two copies does not establish reproduction of the original presented.', ['A more expensive seal.', 'Equipment cost does not supply the original.'], ['The customer’s promise that the copies match.', 'The notary must carry out the required original comparison.'], ['The notary’s signature on both copies in advance.', 'Advance signatures do not supply the original.']],
  ['ct-118', 'copy-process', 'A customer presents an eligible original private document. Which copying process fits the statute?', 'The notary makes or supervises the copy and compares it with the original.', 'The statute requires involvement in reproduction and comparison.', ['Certify an unseen copy mailed by someone else.', 'The required comparison has not occurred.'], ['Compare only the first page of a ten-page copy.', 'Certification concerns an accurate and complete reproduction.'], ['Ask the customer to guarantee the notary’s signature.', 'That does not perform the copy process.']],
  ['ct-119', 'copy-process', 'While comparing an eligible original with its copy, a notary sees an entire paragraph missing. What should happen?', 'Obtain an accurate, complete reproduction before certifying.', 'A materially incomplete copy fails the required comparison.', ['Certify it because most words match.', 'The standard concerns a complete reproduction.'], ['Delete the paragraph from the original.', 'Altering the original is not the copy-certification task.'], ['Charge for the missing paragraph.', 'A fee cannot make an incomplete copy complete.']],
  ['ct-120', 'copy-process', 'A notary supervises copying an eligible signed private letter and checks every page against the original. What may the certificate accurately state?', 'That the copy accurately and completely reproduces the original presented.', 'The described process supports a reproduction certificate within the authorized scope.', ['That the original writer’s opinions are correct.', 'Comparison does not verify the letter’s assertions.'], ['That the letter is a state-issued record.', 'The original’s private character does not change.'], ['That the copy is now an original signature.', 'A certified copy remains a reproduction.']],
  ['ct-121', 'vital', 'A parent asks a Connecticut notary to certify a photocopy of a birth certificate for school enrollment. What should the notary do?', 'Refer the parent to the official vital-record custodian.', 'Vital records are excluded from notarial copy certification.', ['Certify it if the parent presents an original.', 'The original-document requirement does not override the exclusion.'], ['Certify it if the school requests it.', 'The school cannot expand the notary’s statutory authority.'], ['Treat the seal as a registrar’s signature.', 'A notary is not acting as the vital-record custodian.']],
  ['ct-122', 'vital', 'A client has an original marriage record and wants a second “official original” made by a notary. Which response is accurate?', 'Obtain an official certified record from its custodian.', 'A notarial act cannot create an official vital-record original.', ['A notarized photocopy becomes a new state original.', 'The notary cannot create that official record.'], ['The customer can appoint the notary as registrar orally.', 'Customer instructions do not grant registrar authority.'], ['The ordinary copy rule has no vital-record exception.', 'The statute expressly excludes vital records.']],
  ['ct-123', 'vital', 'A customer says a certified death record is too slow to obtain and asks the notary to bypass the custodian. What governs?', 'The vital-record exclusion still applies.', 'Urgency does not expand copy-certification authority.', ['Urgent deadlines waive the exclusion.', 'The stated exclusion does not depend on urgency.'], ['A doubled fee authorizes the bypass.', 'Payment cannot create authority.'], ['A handwritten “official” label cures the problem.', 'A label does not make a notarial copy a custodian-issued record.']],
  ['ct-124', 'vital', 'A clerk says any document bearing an original state seal may be copy-certified by a notary. What should the notary check first?', 'Whether the document is an excluded vital or other protected record.', 'Official appearance does not remove statutory exclusions.', ['Only whether the seal is blue.', 'Seal color does not determine authority.'], ['Only whether the customer is a regular.', 'Customer familiarity does not remove exclusions.'], ['Only whether the copy machine is new.', 'Machine age does not determine the document’s eligibility.']],
  ['ct-125', 'recordable', 'An owner asks for notarial copy certification of a document required to be recorded by a town official. What issue applies?', 'The statutory exclusion for documents required to be recorded by a governmental official.', 'The copy-certification definition contains that exclusion.', ['Any document becomes eligible if it is privately held.', 'Possession does not remove the recordability exclusion.'], ['The customer can waive the recording law.', 'The customer cannot waive statutory limits on the notary.'], ['A property address is enough to authorize certification.', 'An address does not supply copy-certification authority.']],
  ['ct-126', 'recordable', 'An employer asks a notary to copy-certify a federal-agency document whose copying federal law prohibits. What should happen?', 'Decline the prohibited copy certification.', 'Federal copying restrictions are expressly included in the exclusion.', ['Proceed because the employer owns a copier.', 'Owning equipment does not override federal law.'], ['Proceed if the customer signs a waiver.', 'A waiver cannot create prohibited authority.'], ['Certify only the first page to avoid the rule.', 'Partial reproduction does not evade the exclusion.']],
  ['ct-127', 'recordable', 'A client assumes that producing an original automatically makes every document eligible for copy certification. What should the notary explain?', 'The original is necessary, and the statutory exclusions must also be checked.', 'The copy procedure and eligibility limits apply together.', ['The original eliminates every exclusion.', 'The statute still excludes specified documents.'], ['No Connecticut notary may ever certify any copy.', 'The statute permits eligible copies under its procedure.'], ['Only the fee decides eligibility.', 'Payment does not determine the document category.']],
  ['ct-128', 'recordable', 'A business wants an extra copy of a record whose certified copies are obtained through an official custodian. What is the sound first step?', 'Check the statutory exclusions and direct the customer to the proper custodian when applicable.', 'The notary should establish authority before offering a copy certificate.', ['Assume all public records are private documents.', 'A customer’s possession does not change the record category.'], ['Relabel the public record a private letter.', 'Relabeling does not alter the document’s legal character.'], ['Have a coworker use the notary’s seal.', 'Delegation does not solve an authority problem.']],
  ['ct-129', 'custodian-statement', 'For an eligible private document, its custodian signs a statement in the notary’s presence and swears that the attached copy is accurate. What does the notary complete?', 'A jurat for the custodian’s sworn statement.', 'The custodian makes the assertion while the notary administers the sworn act.', ['A guarantee that the original issuer is genuine.', 'The described oath does not authenticate the issuer.'], ['A certificate that the notary personally wrote the original.', 'Those are not the facts of the act.'], ['An appointment application for the custodian.', 'The act is unrelated to appointment.']],
  ['ct-130', 'custodian-statement', 'A receiving agency says it requires a custodian-issued certified record and will not accept an affidavit about a copy. Who decides whether the affidavit meets that filing requirement?', 'The receiving agency applies its own acceptance requirements.', 'A custodian attestation does not force an agency to accept a substitute document.', ['The notary can force acceptance by adding a seal.', 'A seal does not override the agency’s document requirements.'], ['The study site decides official filing sufficiency.', 'This site has no authority over the filing.'], ['The copy machine manufacturer decides.', 'Equipment suppliers do not set official acceptance rules.']],
  ['ct-131', 'custodian-statement', 'A document custodian has signed a copy-accuracy statement but refuses any oath or affirmation. What is missing for the proposed jurat?', 'The custodian’s oath or affirmation.', 'The attestation procedure uses a sworn statement.', ['Only a larger copy of the original.', 'Copy size does not perform the oath.'], ['Only the employer’s advertising seal.', 'An employer seal cannot administer the oath.'], ['Nothing, the statement swears itself.', 'Written wording does not replace the ceremony.']],
  ['ct-132', 'custodian-statement', 'A customer asks the notary to label the custodian’s affidavit as a notary-issued certified birth record. What is the correct response?', 'Keep the act accurately described and refer official vital-record needs to the custodian.', 'A jurat for someone’s statement must not be presented as the notary certifying a vital record.', ['Use the requested label because the customer wrote it.', 'The label would misrepresent the notarial role.'], ['Treat the affidavit as a replacement for every agency’s required record.', 'Acceptance requirements remain with the receiving agency.'], ['Omit the signer’s statement and keep only the seal.', 'A bare seal does not create the requested record.']],
  ['ct-133', 'copy-boundary', 'A notary certifies an eligible copy of a private certificate. Does that establish the issuing business is licensed?', 'No. The certificate concerns accurate reproduction of the original presented.', 'Copy comparison does not investigate the issuer’s legal status.', ['Yes, all copy certificates license the issuer.', 'The act grants no business license.'], ['Yes, if the original has a logo.', 'A logo does not establish licensing.'], ['Yes, if the customer pays the maximum fee.', 'Payment does not expand the certificate’s scope.']],
  ['ct-134', 'copy-boundary', 'An eligible private letter contains an incorrect claim, but the copy reproduces it exactly. What distinction matters?', 'Reproduction accuracy is distinct from the letter’s factual truth.', 'The copy certificate concerns faithful reproduction.', ['A faithful copy proves every claim is true.', 'Copy comparison does not verify underlying claims.'], ['The notary must silently rewrite the copied claim.', 'The notary should not alter a copy while certifying fidelity.'], ['The copy certificate becomes a legal opinion.', 'The act does not provide legal advice.']],
  ['ct-135', 'copy-boundary', 'A recipient asks whether an eligible copy certificate guarantees that a contract is enforceable. What is accurate?', 'It certifies reproduction within the authorized copy procedure.', 'The certificate does not decide the contract’s legal effect.', ['The copy certificate validates every contract term.', 'That exceeds the certificate’s scope.'], ['The notary becomes a contract guarantor.', 'The copy act creates no such guarantee.'], ['The copy becomes a court judgment.', 'A reproduction certificate is not a judgment.']],
  ['ct-136', 'copy-boundary', 'An eligible original has six pages, but a customer wants a five-page reproduction labeled “complete.” What should the notary do?', 'Do not certify that incomplete reproduction as complete.', 'The certificate must accurately describe a complete reproduction of the original.', ['Certify it if the omitted page looks unimportant.', 'The notary cannot call an omitted page complete.'], ['Let the customer insert the sixth page after certification.', 'The notary must compare what is actually certified.'], ['Use a different seal to hide the omission.', 'A seal cannot cure an inaccurate certificate.']],
  ['ct-137', 'journal', 'A new notary asks whether every ordinary Connecticut act must be entered in a journal by statute. What does the manual say?', 'A journal is strongly recommended, with no general state-law requirement.', 'The manual distinguishes the recommendation from a legal mandate.', ['Every act requires a statutory thumbprint journal.', 'That is not the Connecticut rule described.'], ['Journals are forbidden because they are optional.', 'Optional use is permitted and strongly recommended.'], ['A journal automatically replaces an acknowledgment.', 'Records do not replace the act itself.']],
  ['ct-138', 'journal', 'A notary is asked to explain an act performed months ago. Why can a voluntary journal help?', 'It can provide contemporaneous evidence of the procedure used.', 'The manual emphasizes the journal’s protective evidentiary value.', ['It makes every improper act valid.', 'A record does not cure misconduct.'], ['It transfers all responsibility to the signer.', 'A journal does not remove the notary’s duties.'], ['It creates a new commission term.', 'Recordkeeping does not extend authority.']],
  ['ct-139', 'journal', 'An office says keeping a journal is pointless because it is not generally mandatory. What is the manual-supported response?', 'The Secretary strongly recommends one for protection and reliable records.', 'A useful safeguard can be recommended without being a universal mandate.', ['The office must destroy every journal.', 'The manual recommends keeping records.'], ['A journal eliminates the need to check identity.', 'Recordkeeping does not replace identity verification.'], ['Only unpaid acts may be recorded.', 'The recommendation covers notarial acts generally.']],
  ['ct-140', 'journal', 'A notary declined an act after a serious competence concern. What recordkeeping approach does the manual discuss?', 'Document the special circumstances if keeping a journal.', 'The competence guidance discusses documenting circumstances even when refusing an act.', ['Record a false successful notarization.', 'The entry must reflect what actually happened.'], ['Omit the refusal and invent an acknowledgment date.', 'Inventing an act would misrepresent the event.'], ['Have the companion sign the notary’s name.', 'The companion cannot act for the notary.']],
  ['ct-141', 'journal-entry', 'A journal entry contains only “one document, $10.” Which addition best follows the manual?', 'The act’s date, time, type, place and identity information.', 'The recommended entry contains more than the fee and a vague label.', ['An advertisement for the employer.', 'Advertising does not document the act.'], ['The notary’s favorite color.', 'That adds no relevant act evidence.'], ['A claim that every document is lawful.', 'The journal should record facts of the act, not an unsupported guarantee.']],
  ['ct-142', 'journal-entry', 'A notary chooses loose, unnumbered slips for journal entries. Which format does the manual recommend to reduce loss or substitution?', 'A bound book.', 'The manual recommends a bound journal for record integrity.', ['An erasable board cleaned daily.', 'That does not preserve reliable entries.'], ['A pile of unsigned customer invoices only.', 'Invoices omit important act information.'], ['The customer’s social media feed.', 'That does not provide the recommended controlled journal.']],
  ['ct-143', 'journal-entry', 'An entry identifies a customer but omits how identity was established. Which detail should be recorded under the recommendation?', 'The method used to determine identity.', 'Identity method is an expressly recommended journal detail.', ['The brand of the notary’s desk.', 'Desk brand does not establish identity procedure.'], ['The customer’s predicted future address.', 'Predictions do not document the act.'], ['A random ID method to fill the blank.', 'Journal facts must describe the method actually used.']],
  ['ct-144', 'journal-entry', 'A customer paid no fee for an act. What should a journal entry’s fee information reflect?', 'The actual fee, including that no fee was charged.', 'The recommended record describes the fee, if any.', ['The maximum fee even though unpaid.', 'That would misstate the transaction.'], ['A fictional travel charge.', 'The entry should describe actual facts.'], ['The application fee paid years earlier.', 'The entry concerns this notarial act.']],
  ['ct-145', 'seal', 'An ordinary Connecticut notary has no seal. May she perform a proper in-person acknowledgment?', 'Yes, using the required signature and certificate information.', 'A seal is optional for the ordinary commission.', ['No, every ordinary act requires embossing.', 'Connecticut does not impose that general seal requirement.'], ['Yes, without any certificate.', 'Optional equipment does not remove the certificate.'], ['Yes, without the original signature.', 'The original signature is still required.']],
  ['ct-146', 'seal', 'A notary buys an optional seal. What must its identifying name match?', 'The name on the appointment certificate.', 'The prescribed format identifies the commissioned notary.', ['The employer’s trade name only.', 'The seal must identify the notary.'], ['Any nickname the customer prefers.', 'Customer preference does not set the official name.'], ['The character recommender’s name.', 'The recommender is not the commissioned officeholder.']],
  ['ct-147', 'seal', 'A notary places a seal directly over the certificate signature so it becomes unreadable. What does the manual recommend?', 'Place the impression near the signature without covering it.', 'The seal should preserve the signature’s legibility.', ['Add enough impressions to cover all text.', 'Covering the certificate frustrates its purpose.'], ['Omit the original signature next time.', 'A seal cannot replace the original signature.'], ['Let the signer erase the signature afterward.', 'Removing the required signature does not solve placement.']],
  ['ct-148', 'seal', 'An optional seal shows the notary’s name, Notary Public and Connecticut, with expiration on a separate stamp. Is the separate expiration approach recognized?', 'Yes. The prescribed format permits expiration information on a separate stamp.', 'The manual and statute allow that arrangement.', ['No, the expiration must be engraved into an embosser in every case.', 'A separate stamp is allowed.'], ['Yes, and expiration may therefore be omitted everywhere.', 'The expiration information still must be supplied.'], ['Yes, and the seal can replace personal appearance.', 'Equipment does not replace appearance.']],
  ['ct-149', 'seal-control', 'A bank paid for its employee’s notary seal and asks her to leave it for coworkers when she resigns. What should she do?', 'Keep control of her own seal. Coworkers cannot use it.', 'Employer payment does not transfer possession and use authority.', ['Leave it because the bank paid.', 'Payment does not make the commission or seal transferable.'], ['Let the manager lend it out.', 'The manager cannot authorize another person’s use.'], ['Remove her name and keep the old commission active.', 'Altering equipment does not transfer or extend authority.']],
  ['ct-150', 'seal-control', 'A receptionist wants to stamp certificates while the notary is away. What is the proper response?', 'Only the named notary may possess and use that notarial seal.', 'The manual reserves control to the notary whose name appears on it.', ['Permit use for regular customers.', 'Customer familiarity does not authorize delegation.'], ['Permit use if the receptionist signs a confidentiality form.', 'A confidentiality agreement does not grant notarial authority.'], ['Permit use during lunch only.', 'Time of day does not change seal authority.']],
  ['ct-151', 'seal-control', 'A notary’s seal is stolen from an office. What response does the manual support?', 'Report the loss to the authorities and Secretary as directed in the manual.', 'The manual provides a reporting procedure to protect against unauthorized use.', ['Assume any later impression is a valid act.', 'Possession of stolen equipment does not establish a lawful act.'], ['Publish blank sealed certificates to warn customers.', 'Issuing blank sealed certificates creates additional misuse opportunities.'], ['Let a coworker use a substitute with the same name.', 'A coworker cannot assume the commission.']],
  ['ct-152', 'seal-control', 'A notary allows the commission to expire and stops serving. What must happen to the official seal?', 'Destroy or deface it to prevent unauthorized use.', 'The statute and manual address seal destruction upon lapse or expiration.', ['Donate it to the replacement employee for use.', 'The personal seal cannot be transferred for another’s acts.'], ['Keep issuing impressions without signatures.', 'Expired authority does not permit continuing acts.'], ['Use it until the rubber wears out.', 'Equipment condition does not extend the term.']],
  ['ct-153', 'fees', 'In November 2026, a notary proposes a $12 fee for one ordinary notarial act, excluding travel. What current ceiling should be applied?', '$10 for the act.', 'P.A. 26-81 raised the act ceiling to $10 effective July 1, 2026.', ['$5 because the former limit never changed.', 'That amount was superseded by the effective amendment.'], ['$12 whenever the customer agrees.', 'Consent does not override the statutory ceiling.'], ['$120 because that is the application fee.', 'Appointment fees and act fees are separate.']],
  ['ct-154', 'fees', 'A mobile notary prepares a mileage charge in late 2026. What current statutory benchmark should she check?', 'The IRS business standard mileage rate.', 'The amendment uses that rate as the mileage ceiling.', ['A permanent $0.35 rate.', 'The former fixed rate has been superseded.'], ['Any rate printed on a private advertisement.', 'An advertisement does not set the statutory ceiling.'], ['The customer’s income-tax bracket.', 'That does not determine the mileage cap.']],
  ['ct-155', 'fees', 'A notary offers a lawful act without charging. Does the $10 ceiling require collecting $10?', 'No. It is a maximum fee.', 'A cap limits the charge and does not mandate the maximum.', ['Yes, every act must cost exactly $10.', 'The statute sets a ceiling.'], ['Yes, otherwise the commission expires.', 'A voluntary free act does not terminate the commission.'], ['No, because there is no fee limit at all.', 'The current statute does impose a limit.']],
  ['ct-156', 'fees', 'A training handout still lists $5 plus $0.35 per mile. Which source should a November 2026 learner use for that fee rule?', 'The effective 2026 amendment and updated current manual.', 'The effective amendment supersedes the older fee figures.', ['The old handout solely because it was printed first.', 'Earlier publication does not override a later effective law.'], ['A practice score to calculate the fee.', 'Practice results have no role in the statutory fee.'], ['The notary’s desired hourly wage.', 'Desired income does not set the act-fee ceiling.']],
  ['ct-157', 'changes', 'A commissioned notary changes her surname but has not yet received the replacement certificate. What controls the official name-change transition?', 'The replacement certificate’s issuance date.', 'The manual and statute use issuance of the replacement certificate for the official transition.', ['The date she orders a new pen.', 'Equipment purchases do not set the effective name change.'], ['The customer’s preferred date.', 'A customer does not control the official transition.'], ['The end of the next five-year term only.', 'The name-change procedure can operate during the term.']],
  ['ct-158', 'changes', 'A Connecticut resident notary moves to a different town. What should she address?', 'Notify the Secretary within 30 days and handle the required new-town recording.', 'The address change affects the official records and applicable town filing.', ['Only tell her private seal vendor.', 'A vendor notification does not update state and town records.'], ['Assume a new address automatically cancels every prior act.', 'The change procedure does not automatically invalidate earlier acts.'], ['Begin a fresh five-year term without applying.', 'Moving does not grant a new appointment term.']],
  ['ct-159', 'changes', 'A nonresident notary moves her principal Connecticut business to another Connecticut town. What record needs attention?', 'Report the business-address change and complete applicable replacement-certificate recording.', 'The nonresident’s principal-business address determines the required Connecticut recording town.', ['Only her vacation address.', 'The changed qualifying business address is relevant.'], ['Only the customer mailing list.', 'A customer list does not update official records.'], ['Nothing until the stamp wears out.', 'Equipment wear does not set notification duties.']],
  ['ct-160', 'changes', 'After receiving a replacement certificate with a new official name, a notary keeps using an old-name seal. What should change?', 'Use matching new-name equipment if using a seal.', 'The official name and seal must correspond after the replacement takes effect.', ['Keep the old name indefinitely if recognized.', 'Recognition does not override the official name requirement.'], ['Let customers choose between both identities.', 'The customer does not choose the notary’s official identity.'], ['Have the employer notarize under the old seal.', 'The seal cannot be delegated to the employer.']],
  ['ct-161', 'signatory', 'A notary is the borrower named and signing as a party to a loan agreement. May she notarize that document?', 'No. She is a signatory of the document.', 'Section 3-94g disqualifies a document signatory.', ['Yes, if the lender permits it.', 'The lender cannot waive statutory disqualification.'], ['Yes, if another employee watches.', 'A witness does not cure signatory disqualification.'], ['Yes, if she charges no fee.', 'The prohibition does not depend on payment.']],
  ['ct-162', 'signatory', 'A notary needs an acknowledgment of his own signature on a personal authorization. What should he arrange?', 'A different authorized notarial officer.', 'The notary cannot notarize his own signature.', ['Use his own seal without a signature.', 'A bare seal does not cure self-notarization.'], ['Ask the customer to sign his certificate for him.', 'A customer cannot complete the notary’s official signature.'], ['Write a statement waiving his conflict.', 'A personal waiver does not remove statutory disqualification.']],
  ['ct-163', 'signatory', 'A notary merely witnessed another person signing and did not sign as a transaction party. What distinction does the manual make?', 'A mere witness to signing is distinguished from a disqualified document signatory.', 'The manual expressly discusses the witness-only distinction.', ['Every witness is always disqualified from every act.', 'The manual does not impose that blanket rule.'], ['Witnessing automatically proves identity.', 'Identity must still be established through an authorized basis.'], ['Witnessing replaces any oath required.', 'An oath or affirmation still must occur for a jurat.']],
  ['ct-164', 'signatory', 'A notary signed an agreement as a buyer and is asked to notarize the seller’s signature on the same document. What governs?', 'The notary is disqualified as a signatory of that document.', 'The disqualification concerns the document, including this party-signatory role.', ['Only notarizing the buyer’s signature would be a problem.', 'The statute disqualifies a signatory from the notarial act on the document.'], ['A different colored pen removes the conflict.', 'Ink color does not change signatory status.'], ['The seller can consent to erase the prohibition.', 'Consent does not override the statute.']],
  ['ct-165', 'family-interest', 'A notary’s adult sister requests an act on a document the notary has not signed. What should the notary consider?', 'Impartiality and the Secretary’s strong caution for family transactions.', 'Family involvement requires caution and a separate check for signatory status.', ['Every relative transaction is automatically the same as self-notarization.', 'Family status and being a signatory are distinct.'], ['Family members need no identification or ceremony.', 'The usual requirements still apply.'], ['The relationship requires charging twice the maximum fee.', 'The relationship does not authorize exceeding the fee cap.']],
  ['ct-166', 'family-interest', 'A proposed transaction would benefit the notary financially, although she is not a signatory. What is the manual-supported approach?', 'Exercise great caution about impartiality and consider voluntary disqualification.', 'The manual specifically warns about beneficial interests.', ['Financial benefit proves impartiality.', 'A benefit can create an impartiality concern.'], ['All requirements disappear when the notary benefits.', 'The act requirements remain.'], ['The notary should pressure the signer to complete the deal.', 'The notary must remain impartial.']],
  ['ct-167', 'family-interest', 'A notary chooses to have an independent notary handle a family transaction. Is that consistent with the manual?', 'Yes. Voluntary disqualification may be appropriate.', 'The manual recognizes voluntary disqualification in such circumstances.', ['No, relatives must always use that family notary.', 'The manual imposes no such obligation.'], ['No, family transactions eliminate the need for any notary.', 'The relationship does not eliminate the requested act.'], ['No, only the employer may choose the notary.', 'The employer has no blanket exclusive choice.']],
  ['ct-168', 'family-interest', 'A notary says her cousin’s request is automatically safe because she is not signing the document. What else needs attention?', 'Impartiality and all other requirements for the act.', 'Absence of signatory status does not settle every concern.', ['Nothing, the cousin can skip appearance.', 'Family relationship does not waive appearance.'], ['Nothing, the cousin can complete the notary’s certificate later.', 'The notary must complete an accurate certificate.'], ['Only whether they share a surname.', 'A shared surname does not determine all impartiality concerns.']],
  ['ct-169', 'influence', 'While notarizing a loan, a notary tells the signer the deal is excellent and should be signed immediately. What boundary is implicated?', 'The duty to remain impartial and avoid influencing the transaction.', 'The manual cautions against advising the signer to enter the transaction.', ['The notary’s duty to sell the lender’s products.', 'The commission creates no sales duty.'], ['An exception for confident opinions.', 'Confidence does not remove the impartiality boundary.'], ['Only the handwriting-sample requirement.', 'The issue concerns conduct during this transaction.']],
  ['ct-170', 'influence', 'A signer asks a nonattorney notary whether the agreement is legally better than another offer. What is the appropriate response?', 'Refer the legal comparison to qualified counsel.', 'The notary should avoid giving legal advice or influencing the decision.', ['Choose the agreement paying the employer more.', 'That would compromise impartiality.'], ['Use the seal to rank the offers.', 'The seal has no authority to rank contracts.'], ['Guarantee either contract after charging a fee.', 'The commission does not authorize that legal guarantee.']],
  ['ct-171', 'influence', 'A notary explains how an affirmation works without recommending whether the signer should accept the contract. Which boundary does that respect?', 'Procedural explanation while maintaining impartiality.', 'The explanation concerns the notarial ceremony.', ['A duty to negotiate the contract price.', 'The notary has not been authorized by the commission to negotiate for the signer.'], ['Permission to provide immigration representation.', 'The commission alone grants no such authority.'], ['A requirement to endorse the contract.', 'The notary should not endorse the transaction.']],
  ['ct-172', 'influence', 'An employer tells a notary to withhold service until the customer buys another product. What should the notary consider?', 'The impartiality duty and the rule against unreasonable refusal of lawful service.', 'A sales condition can conflict with the notary’s public role.', ['The commission belongs to the sales department.', 'Notarial authority is personal.'], ['Any business incentive overrides notarial requirements.', 'Business incentives do not override those duties.'], ['The notary may certify a purchase that never occurred.', 'A notary must not certify false facts.']],
  ['ct-173', 'fraud', 'A customer asks a notary to certify that an absent partner appeared. What should happen?', 'Refuse the false appearance certificate.', 'A certificate intentionally misstating appearance would deceive.', ['Proceed if the customer accepts responsibility.', 'A customer cannot authorize official deception.'], ['Proceed if the partner is well liked.', 'Reputation does not establish appearance.'], ['Charge extra for the unusual request.', 'A higher fee does not authorize a false act.']],
  ['ct-174', 'fraud', 'A manager threatens dismissal unless a notary certifies an oath that never occurred. What is the notary’s duty?', 'Refuse to make the false official certificate.', 'Employer pressure does not authorize official misconduct.', ['The manager’s instruction makes it lawful.', 'An employer cannot override notarial duties.'], ['Use a blank date to make the false oath acceptable.', 'An omitted date does not create an oath.'], ['Let the manager hold the seal and decide.', 'Seal control and authority cannot be delegated that way.']],
  ['ct-175', 'fraud', 'A signer asks the notary to leave a certificate blank so its facts can be invented later. What should the notary do?', 'Decline to issue a certificate for fabricated later facts.', 'The notarial certificate must reflect the actual act.', ['Agree because the signer owns the paper.', 'Paper ownership does not authorize official deception.'], ['Agree if the paper is expensive.', 'Paper value is irrelevant to certificate accuracy.'], ['Agree but hide the notary’s name.', 'Concealing identification does not cure the problem.']],
  ['ct-176', 'fraud', 'A notary discovers a request is designed to falsely show a deceased signer appeared today. What is appropriate?', 'Refuse the deceptive act.', 'The requested appearance certification cannot truthfully be made.', ['Use an old photograph as today’s appearance.', 'A photograph does not establish today’s ceremony.'], ['Let the family choose an appearance date.', 'Family wishes cannot establish false facts.'], ['Proceed without charging.', 'Free service is still subject to the fraud prohibition.']],
  ['ct-177', 'refusal', 'A notary dislikes a customer’s national origin although the lawful request meets all act requirements. What does the manual say about refusal on that basis?', 'It is an unlawful basis for refusing service.', 'The refusal guidance specifically addresses personal-characteristic discrimination.', ['It is always the notary’s unrestricted preference.', 'The public-service duty limits unreasonable refusal.'], ['It is cured by charging a higher fee.', 'A higher fee does not cure discrimination.'], ['It is permitted whenever the customer is unfamiliar.', 'Unfamiliarity calls for identity verification, not discrimination.']],
  ['ct-178', 'refusal', 'A requester has not established identity through any authorized method and asks the notary to proceed anyway. What is appropriate?', 'Resolve the identity deficiency before performing the act.', 'The duty against unreasonable refusal does not eliminate identity requirements.', ['Proceed because every refusal is forbidden.', 'The manual recognizes genuine identity concerns.'], ['Assume identity from the offered fee.', 'Payment does not establish identity.'], ['Ask the customer to invent a second identity document.', 'Fabricated documents do not satisfy the rule.']],
  ['ct-179', 'refusal', 'An employer-only notarial service receives a request from the general public. What does the manual say about such service limits?', 'Employer-only service can be a reasonable basis, with reasonableness evaluated case by case.', 'The manual gives employer-only service as an example rather than an unlimited exemption.', ['Every such refusal is automatically a crime.', 'The manual recognizes possible reasonable service limitations.'], ['Employer policy authorizes false certificates.', 'A service limit never authorizes deception.'], ['The notary may discriminate against protected groups.', 'The public-service rule still forbids that basis.']],
  ['ct-180', 'refusal', 'A notary is unsure whether a remote document falls on the prohibited list. What may she do?', 'Check the statutory restrictions and decline the remote act if the concern remains.', 'The manual urges caution with excluded remote documents.', ['Proceed because remote service is mandatory.', 'Remote service is optional.'], ['Use the customer’s waiver to override the list.', 'A waiver cannot remove the statutory exclusions.'], ['Change the document’s title to avoid checking.', 'Renaming a document does not change the transaction.']],
  ['ct-181', 'promotion', 'A business asks a notary to place her official seal on an advertisement saying she endorses its product. What should she do?', 'Decline the use of title or seal for the promotional endorsement.', 'Section 3-94h prohibits this promotional use.', ['Allow it if the advertisement pays well.', 'Compensation does not waive the prohibition.'], ['Allow it if the product is useful.', 'Product quality does not authorize official endorsement.'], ['Allow it if the customer supplies the ink.', 'Ink ownership has no effect on authority.']],
  ['ct-182', 'promotion', 'A nonattorney notary without federal authorization is asked to advise on immigration status. What is the proper response?', 'Refer the legal advice request to an authorized professional.', 'The commission alone does not authorize immigration legal advice.', ['Give legal advice because all notaries are attorneys.', 'A notary commission does not confer attorney status.'], ['Provide the advice only in another language.', 'Language does not remove the restriction.'], ['Stamp a legal opinion instead of signing it.', 'Using a stamp does not create legal-advice authority.']],
  ['ct-183', 'promotion', 'A notary advertises as “notario publico” with no attorney qualification and no required nonattorney notice. Which rule needs attention?', 'The specific title and notice restrictions in section 3-95a.', 'The statute addresses potentially misleading use of those titles.', ['The title grants broader foreign legal authority automatically.', 'A translated title does not expand the Connecticut commission.'], ['Only the ink color matters.', 'The issue concerns title use and required disclosure.'], ['No rule applies because the words are not English.', 'The statute expressly addresses those words.']],
  ['ct-184', 'promotion', 'A signer asks the notary to certify a translation the notary personally prepared. What does the manual direct?', 'Use another authorized oath administrator for the translator’s sworn statement.', 'The manual says a notary cannot prepare and notarize the same translation accuracy statement.', ['The notary may swear to herself.', 'A notary cannot administer her own oath for this statement.'], ['The seal proves translation accuracy automatically.', 'The commission does not itself certify translation skill.'], ['The notary’s employer may sign the notary’s name.', 'The employer cannot perform the notary’s personal act.']],
  ['ct-185', 'remote-identity', 'During an otherwise eligible remote act, a signer presents a current government passport with photograph, name and signature. Which identity route may apply?', 'The remote government-ID route under section 3-95b.', 'Remote documentary identification has its own statutory standard.', ['The remote act always requires two signed documents.', 'That is the separate in-person documentary rule.'], ['A passport removes every other remote requirement.', 'Identity is only one part of the remote procedure.'], ['The notary may now act from any state.', 'The notary’s Connecticut location requirement remains.']],
  ['ct-186', 'remote-identity', 'A remote signer offers an expired government ID as the only identity basis. What is the problem?', 'The remote government-ID option requires an unexpired document.', 'The statutory option expressly requires a document that has not expired.', ['Expired IDs are automatically personal knowledge.', 'A document’s existence does not create personal knowledge.'], ['A blurred video cures the expiration.', 'Video quality cannot change validity dates.'], ['Paying a premium makes the ID current.', 'Payment does not renew identification.']],
  ['ct-187', 'remote-identity', 'A remote platform offers just one third-party identity-proofing process, with no other identification route used. What should the notary check?', 'The statute requires at least two different identity-proofing processes for that route.', 'A single service process alone does not meet the stated proofing option.', ['Any platform login completes proofing automatically.', 'Logging in is not the stated statutory standard.'], ['The signer’s email signature replaces every identity check.', 'An email signature alone does not satisfy this route.'], ['The notary can certify identity after the session without evidence.', 'The notary must reasonably identify the signer at the act.']],
  ['ct-188', 'remote-identity', 'A credible witness joins a remote session and knows the signer. What else must the notary establish?', 'The witness’s identity through an authorized remote method and the required oath or affirmation.', 'The remote witness option has its own presence, identification and sworn-statement requirements.', ['The witness’s opinion that video looks clear only.', 'Video quality alone does not identify the witness.'], ['The witness must always have a Connecticut home address.', 'The cited remote-witness provision focuses on the specified identity and communication requirements.'], ['The witness may remain unidentified because the signer knows him.', 'The notary must reasonably identify the witness.']],
  ['ct-189', 'remote-connection', 'A customer sends a recorded video and asks the notary to treat it as a live remote meeting. What is missing?', 'Simultaneous real-time communication by sight and sound.', 'A recording does not allow the required interactive meeting.', ['A larger email attachment.', 'File size does not provide simultaneous interaction.'], ['A second recording of the same event.', 'Another recording is still not real-time communication.'], ['A printed photograph beside the screen.', 'A photograph does not create live interaction.']],
  ['ct-190', 'remote-connection', 'During a remote session the notary can hear the signer but has no visual connection. What should be addressed?', 'The statutory communication requirements, including any applicable disability accommodation.', 'An ordinary audio-only connection does not meet the sight-and-sound rule.', ['Proceed automatically because audio is always enough.', 'The statute generally requires both sight and sound.'], ['Replace the visual connection with the customer’s fee.', 'Payment is unrelated to communication requirements.'], ['Use a coworker’s description as live video.', 'A description does not provide the required visual interaction.']],
  ['ct-191', 'remote-connection', 'A Connecticut notary remains in Hartford while a signer attends by suitable video technology. Does video alone complete all requirements?', 'No. Identity, document eligibility, execution and delivery requirements also apply.', 'Technology is one part of the remote process.', ['Yes, all documents become eligible once video works.', 'The statutory exclusions still apply.'], ['Yes, the certificate can say the signer attended physically.', 'The certificate must describe technology appearance accurately.'], ['Yes, no original document is needed afterward.', 'The statute requires original delivery.']],
  ['ct-192', 'remote-connection', 'A notary prefers to offer only in-person service and declines an otherwise eligible remote method. Does Connecticut require remote service?', 'No. Remote notarization is optional.', 'The manual and statute preserve the notary’s ability to decline remote methods.', ['Yes, owning a camera makes remote service mandatory.', 'Equipment ownership creates no such duty.'], ['Yes, every online request must be accepted.', 'The statute does not impose mandatory remote service.'], ['No, because all remote acts are forbidden.', 'Eligible remote acts are permitted under the separate procedure.']],
  ['ct-193', 'remote-paper', 'A signer completes an eligible remote appearance and sends only a scanned image afterward. What remains under the paper procedure?', 'Delivery of the signed original to the notary for completion.', 'The statute requires mailing or other delivery of the signed original.', ['The scan automatically replaces the original.', 'That omits the statutory delivery step.'], ['The notary may sign the signer’s name on new paper.', 'That does not provide the signer’s original record.'], ['The video provider can waive the statute.', 'A platform cannot remove the delivery requirement.']],
  ['ct-194', 'remote-paper', 'A notary receives the original several days after witnessing the remote signature. Which date and time govern the remote notarization?', 'The date and time the signature was witnessed through communication technology.', 'Section 3-95b(e) supplies the remote-specific rule.', ['Always the original’s arrival date.', 'The statute identifies the technology-witnessed signing time.'], ['The package’s shipping estimate.', 'An estimate does not establish the act date.'], ['Any later date selected by the customer.', 'Customer preference does not set the statutory date.']],
  ['ct-195', 'remote-paper', 'A remote acknowledgment certificate still says the signer appeared physically in the office. What should be addressed?', 'Use accurate communication-technology appearance wording.', 'The current manual instructs adapting the appearance language for remote acts.', ['Leave the physical-appearance claim unchanged.', 'That would misdescribe the remote appearance.'], ['Remove the signer’s name instead.', 'Omitting identity does not fix the appearance description.'], ['Treat the video as a town-clerk filing.', 'Video attendance does not record an appointment.']],
  ['ct-196', 'remote-paper', 'A platform proposes fully electronic signatures for Connecticut remote notarization based solely on its standard template. What should the notary follow?', 'The current Connecticut paper and wet-ink instructions and applicable statute.', 'The current manual directs paper execution for these remote acts.', ['Any platform’s nationwide default controls.', 'A vendor template cannot override Connecticut requirements.'], ['A typed customer name always replaces the original.', 'The stated procedure requires the signed original.'], ['The study site’s practice settings control execution.', 'Practice configuration does not govern official acts.']],
  ['ct-197', 'remote-limits', 'A customer requests remote acknowledgment of a power of attorney. What restriction applies?', 'It falls within the remote exclusions in section 3-95b(i).', 'A power of attorney is specifically listed.', ['All powers of attorney become eligible if scanned.', 'Scanning does not remove the statutory exclusion.'], ['A witness can waive the exclusion.', 'Witness consent cannot change the statute.'], ['The fee cap is the only restriction.', 'Document eligibility is a separate requirement.']],
  ['ct-198', 'remote-limits', 'A lawyer requests remote acknowledgment connected with executing a will or codicil. What should the notary check?', 'The express will and codicil exclusion.', 'Section 3-95b(i) lists those acts.', ['The lawyer’s request overrides all restrictions.', 'An attorney’s request does not waive statutory exclusions.'], ['A will is eligible whenever the signer is elderly.', 'Age does not remove the exclusion.'], ['A recording turns the will into an ordinary private letter.', 'Recording does not change the transaction’s character.']],
  ['ct-199', 'remote-limits', 'A closing coordinator asks a Connecticut notary to handle a real-estate closing remotely. What should the notary identify?', 'The statutory remote restriction for a real-estate closing.', 'Section 3-95b(i) expressly includes that category.', ['Every real-estate closing is permitted remotely if the notary has a seal.', 'Equipment does not remove the restriction.'], ['Only the notary’s preference matters.', 'Statutory document limits apply regardless of preference.'], ['A larger travel fee authorizes the act.', 'Fees do not expand remote authority.']],
  ['ct-200', 'remote-limits', 'A client asks for remote acknowledgment of a living will. Which source should guide the notary?', 'The listed exclusions in section 3-95b(i).', 'The living-will category is expressly listed in the remote restrictions.', ['The rule for copying a private letter only.', 'Copy rules do not answer this remote-execution question.'], ['A customer waiver of health-care formalities.', 'A customer cannot waive statutory remote restrictions.'], ['The practice site’s all-correct screen.', 'Practice performance does not authorize an official act.']],
  ['ct-201', 'remote-record', 'A notary wants to record remote sessions. What does the current manual say about retention?', 'It strongly recommends keeping a recording for at least 10 years.', 'The manual describes this as a recommendation and says law does not require a recording.', ['A recording is always a mandatory lifetime state record.', 'That misstates the recommendation and duration.'], ['All remote recordings must be erased immediately.', 'The manual recommends retention.'], ['Recording replaces delivery of the signed original.', 'Video retention and original delivery are separate.']],
  ['ct-202', 'remote-record', 'A signer outside Connecticut seeks an eligible remote act. Which additional issue belongs in the notary’s review?', 'The record’s qualifying Connecticut connection or other statutory basis under section 3-95b(c).', 'The statute adds conditions for records involving an out-of-state signer.', ['The signer must always be a Connecticut resident.', 'The statute does not impose that blanket residency rule on the signer.'], ['The notary can move out of Connecticut for convenience.', 'The notary must remain within Connecticut.'], ['The signer’s foreign address waives identity checks.', 'Identity requirements still apply.']],
  ['ct-203', 'remote-record', 'A notary keeps a voluntary journal of a remote act. Which additional details does the manual recommend?', 'The signer’s location, communication method and whether a recording was retained.', 'The remote-journal section adds these details to the ordinary recommendations.', ['Only the internet provider’s advertising slogan.', 'An advertisement does not document the act.'], ['A claim that the signer attended physically.', 'That would misstate the remote appearance.'], ['A guarantee of every statement in the document.', 'The journal does not expand the notary’s factual role.']],
];
